def transform(grid):
    """Restore masked 6s by the grid's demonstrated symmetries.

    Clear cells are invariant under main-diagonal transpose and reflection
    across the horizontal midline (row r maps to row 31-r). A masked cell is
    filled from any clear member of its symmetry orbit.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            todo = [(r, c)]
            seen = {(r, c)}
            value = None
            while todo and value is None:
                y, x = todo.pop()
                for a, b in ((x, y), (31-y, x)):
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen:
                        seen.add((a, b))
                        if grid[a][b] != 6:
                            value = grid[a][b]
                            break
                        todo.append((a, b))
            if value is not None:
                out[r][c] = value
    return out
